"""Writes tools/stats/cases_t7.txt: dbscan, procrustes, hidden Markov models, barttest, friedman, designs."""
import os
here = os.path.dirname(os.path.abspath(__file__))
PRE = ("Xd=[x(1:40)' y(1:40)']; Xd(21:40,:)=Xd(21:40,:)+2.5; Yd=Xd*[cos(0.5) -sin(0.5);sin(0.5) cos(0.5)]*1.7+[1 2]; TR=[0.9 0.1;0.2 0.8]; EM=[0.7 0.2 0.1;0.1 0.3 0.6]; "
       "sq=[1 1 2 3 3 2 1 3 3 2 1 1 2 3]; st=[1 1 1 2 2 2 1 2 2 2 1 1 1 2]; fr=[x(1:12)' y(1:12)' x(13:24)']+repmat([0 0.5 1],12,1); ")
L = ["# generated by make_t7_cases.py"]
def add(cs, fmt):
    for c in cs: L.append(fmt.replace("{c}", c))
add(["dbscan(Xd,0.5,3)", "dbscan(Xd,0.3,2)", "dbscan(Xd,1,5)", "dbscan(Xd,0.5,3,'Distance','cityblock')", "dbscan(Xd,0.5,3,'Distance','chebychev')", "dbscan(Xd,0.2,3)", "dbscan(Xd,5,3)", "dbscan(Xd,0.5,1)", "dbscan(Xd,0.5,3,'Distance','minkowski','P',3)", "dbscan(Xd,0.1,3,'Distance','cosine')",
     "dbscan(Xd,-1,3)", "dbscan(Xd,0.5,0)", "dbscan(Xd,0.5)", "dbscan(Xd,0.5,3,'Foo',1)", "dbscan([Xd;NaN 1],0.5,3)", "dbscan(Xd,0.5,3,'Distance','seuclidean')", "dbscan(Xd,0.5,3,'Distance','mahalanobis')", "dbscan(Xd,0.5,3,'Distance','hamming')", "dbscan(single(Xd),0.5,3)", "dbscan(Xd(:,1),0.1,3)"], "[a_,b_] = {c}; r = {a_,b_};")
add(["procrustes(Xd,Yd)", "procrustes(Xd,Yd,'Scaling',false)", "procrustes(Xd,Yd,'Reflection',false)", "procrustes(Xd,Yd,'Reflection',true)", "procrustes(Xd,Yd(:,1:2)*[1 0;0 -1])", "procrustes(Xd,Yd(1:10,:))", "procrustes(Xd,Yd,'Foo',1)", "procrustes(Xd,[Yd Yd(:,1)])", "procrustes(Xd(:,1),Yd(:,1))", "procrustes(Xd,Yd,'Scaling',false,'Reflection','best')", "procrustes(single(Xd),single(Yd))", "procrustes(Xd,Xd)"], "[a_,b_,c_] = {c}; r = {a_,b_,c_.T,c_.b,c_.c};")
add(["hmmdecode(sq,TR,EM)", "hmmdecode(sq,TR,EM,'Symbols',[1 2 3])", "hmmdecode([1 2],TR,EM)", "hmmdecode(sq,TR,EM(:,1:2))", "hmmdecode(sq,[0.5 0.5;0.5 0.5;1 0],EM)", "hmmdecode(sq,TR,[EM;EM])", "hmmdecode(sq(1:3),TR,EM)", "hmmdecode(single(sq),TR,EM)", "hmmdecode(sq,TR,EM,'Foo',1)", "hmmdecode({'a','b','a'},TR,[0.5 0.5;0.2 0.8],'Symbols',{'a','b'})"], "[a_,b_,c_,d_,e_] = {c}; r = {a_,b_,c_,d_,e_};")
add(["hmmviterbi(sq,TR,EM)", "hmmviterbi(sq,TR,EM,'Statenames',{'x','y'})", "hmmviterbi(sq,TR,EM,'Symbols',[3 2 1])", "hmmviterbi(sq,TR,EM,'Foo',1)", "hmmviterbi([],TR,EM)", "hmmviterbi(sq,TR,EM(:,1:2))", "hmmviterbi([1 4],TR,EM)", "hmmviterbi(sq,eye(2),EM)"], "[a_,b_] = {c}; r = {a_,b_};")
add(["hmmestimate(sq,st)", "hmmestimate(sq,st,'Pseudoemissions',ones(2,3))", "hmmestimate(sq,st,'Pseudotransitions',ones(2))", "hmmestimate(sq,st,'Symbols',[1 2 3 4])", "hmmestimate(sq,st(1:5))", "hmmestimate(sq,[st(1:13) 3])", "hmmestimate(sq,st,'Foo',1)", "hmmestimate(sq,st,'Statenames',{'a','b'})", "hmmestimate(sq,st,'Pseudoemissions',ones(2,2))", "hmmestimate({'a','b','a','b'},[1 2 1 1])", "hmmestimate(sq,sq)"], "[a_,b_] = {c}; r = {a_,b_};")
add(["barttest(fr,0.05)", "barttest(fr)", "barttest(fr,0.5)", "barttest(fr(:,1:2),0.05)", "barttest(fr,2)", "barttest(fr(1,:))", "barttest(fr(:,1))", "barttest(single(fr))", "barttest([fr fr(:,1)])", "barttest(randn_(3))"][:-1], "[a_,b_,c_] = {c}; r = {a_,b_,c_};")
add(["bbdesign(3)", "bbdesign(4)", "bbdesign(3,'center',1)", "bbdesign(3,'center',5)", "bbdesign(5)", "bbdesign(2)", "bbdesign()", "bbdesign(3,'foo',1)", "bbdesign(5)"], "[a_,b_] = {c}; r = {a_,b_};")
L = [L[0]] + [PRE + l for l in L[1:]]
with open(os.path.join(here, "cases_t7.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
